import { Table, BooleanColumn, StringColumn, IntegerColumn, ReferenceColumn } from '../../db'

export const sys_ui_list_element = Table({
    actions: ['read', 'update', 'delete', 'create'],
    allowWebServiceAccess: true,
    attributes: {
        forcePrimaryKeyOrdering: true,
        no_audit_delete: true,
    },
    label: 'List Element',
    name: 'sys_ui_list_element',
    schema: {
        max_value: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Show the maximum value for this field in the list',
                    label: 'Max value',
                    plural: 'Max values',
                },
            ],
        }),

        sum: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Show the total value for this field in the list',
                    label: 'Sum',
                    plural: 'Sums',
                },
            ],
        }),

        element: StringColumn({
            label: 'Element',
            maxLength: 255,
        }),

        min_value: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Show the minimum value for this field in the list',
                    label: 'Min value',
                    plural: 'Min values',
                },
            ],
        }),

        position: IntegerColumn({
            label: 'Position',
        }),

        list_id: ReferenceColumn({
            cascadeRule: 'delete',
            label: 'List ID',
            referenceTable: 'sys_ui_list',
        }),

        average_value: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Show the average value for this field in the list',
                    label: 'Average value',
                    plural: 'Average values',
                },
            ],
        }),
    },
})
